put('u3-2','ablauf',2,'order','Sortieren Sie den Ablauf einer normalen Hoodie-Bestellung bei CampusPrint.',{steps:[{id:'c',text:'Druckdatei prüfen'},{id:'d',text:'Druckauftrag freigeben'},{id:'a',text:'Bestellung eingegangen'},{id:'b',text:'Kundendaten erfassen'}],correct:['a','b','c','d'],solution:'Sinnvolle Reihenfolge: Bestellung eingegangen → Kundendaten erfassen → Druckdatei prüfen → Druckauftrag freigeben.'});
put('u3-3','ablauf',2,'slots','Setzen Sie die passenden Symbole in das Mini-Diagramm „Datei prüfen“. Ein Symbol aus der Auswahl bleibt übrig.',{layout:'sequence',slots:['Start: Datei liegt vor','Task: Datei prüfen','Task: Dateiname ergänzen','Ende: Datei geprüft'],choices:['xor','task','start','end'],correct:['start','task','task','end'],solution:'Für den Ablauf werden Start, zwei Tätigkeiten und ein Endereignis benötigt. Das XOR bleibt ungenutzt, weil keine Entscheidung modelliert wird.'});
