export const GLOSSARY=[
['BPMN','Business Process Model and Notation: standardisierte grafische Sprache für Geschäftsprozesse.'],
['Geschäftsprozess','Zusammenhängende Tätigkeiten und Entscheidungen, die zu einem Ergebnis für Kunden oder Unternehmen führen.'],
['Startereignis','Ereignis mit dünnem Kreisrand, das den Prozessbeginn kennzeichnet.'],
['Endereignis','Ereignis mit dickem Kreisrand, das einen Ablaufzweig beendet.'],
['Task','Tätigkeit; konkreter Arbeitsschritt, dargestellt als abgerundetes Rechteck.'],
['Sequenzfluss','Durchgezogene Verbindung mit gefüllter Pfeilspitze, die die Ausführungsreihenfolge zeigt.'],
['Gateway','Verzweigungs- oder Zusammenführungselement in einem Prozessdiagramm.'],
['XOR-Gateway','Exklusives Gateway: bei einer Aufspaltung wird genau ein alternativer Weg durchlaufen.'],
['Bedingung','Beschriftung eines ausgehenden Flusses, zum Beispiel „Ja“ oder „Nein“.'],
['draw.io','Grafischer Editor, auch diagrams.net genannt; kann BPMN-Formen darstellen.'],
['Prozessmodell','Grafische vereinfachte Darstellung eines Arbeitsablaufs mit Ereignissen, Tätigkeiten und Entscheidungen.'],
['Object Management Group (OMG)','Organisation, die unter anderem den BPMN-Standard weiterführt.'],
['Pool','Eigenständiger Prozessbeteiligter in BPMN; wird erst in einer späteren Einheit vertieft.'],
['Lane','Unterteilung eines Pools nach Rollen oder Abteilungen; folgt in einer späteren Einheit.'],
['AND-Gateway','Paralleles Gateway, das in UE 3 eingeführt wird.']
];
export function expectedValue(t){if(t.type==='slots')return t.correct; if(t.type==='category'||t.type==='match')return Object.fromEntries(t.items.map((x,i)=>[String(i),x.answer]));return t.correct;}
export function grade(t,v){
 if(t.type==='text')return null;
 if(t.type==='single')return Number.isInteger(v)&&v===t.correct;
 if(t.type==='tf')return typeof v==='boolean'&&v===t.correct;
 if(t.type==='multi')return Array.isArray(v)&&v.length===t.correct.length&&new Set(v).size===v.length&&[...v].sort((a,b)=>a-b).join('|')===[...t.correct].sort((a,b)=>a-b).join('|');
 if(t.type==='order')return Array.isArray(v)&&v.length===t.correct.length&&v.join('|')===t.correct.join('|');
 if(t.type==='slots')return Array.isArray(v)&&v.length===t.correct.length&&v.every((x,i)=>x===t.correct[i]);
 if(t.type==='category'||t.type==='match')return v&&typeof v==='object'&&t.items.every((x,i)=>v[i]===x.answer);
 return false;
}
export function taskXp(t){return ({1:20,2:35,3:55})[t.afb]+(t.bonus?25:0)+(t.chapter==='test'?10:0);}
export function earnedXp(p){return ALL_TASKS.reduce((n,t)=>n+(p.answers?.[t.id]?.correct?taskXp(t):0),0);}
export function wallet(p){return Math.max(0,earnedXp(p)-SHOP.filter(x=>p.owned?.includes(x.id)).reduce((n,x)=>n+x.price,0));}
export function completedCount(p){return TASKS.filter(t=>p.answers?.[t.id]?.correct).length;}
export function newProgress(){return {answers:{},owned:[],appearance:{avatar:'default',pet:null,outfit:null},skills:{},lastChapter:'start',updatedAt:null};}
